package pcidb

import (
	_ "embed"
)

// The tables are generated by gen.go.
//
// Each table is a sequence of fixed-size records sorted by key: a big-endian key
// followed by a big-endian offset of the name in the names blob.
//
// The names blob is a sequence of length-prefixed (one byte) names.
//
// The tables are embedded as strings, so they stay in read-only memory,
// and lookups don't allocate.
var (
	//go:embed names.bin
	names string

	//go:embed classes.bin
	classes string

	//go:embed subclasses.bin
	subclasses string

	//go:embed vendors.bin
	vendors string

	//go:embed products.bin
	products string
)

// offsetSize is the size of the name offset in table records.
const offsetSize = 3

// lookup finds the name for the key in the table with the given key size (1, 2 or 4 bytes).
func lookup(table string, keySize int, key uint32) (string, bool) {
	recordSize := keySize + offsetSize

	lo, hi := 0, len(table)/recordSize

	for lo < hi {
		mid := int(uint(lo+hi) >> 1)
		pos := mid * recordSize

		switch recordKey := readKey(table, pos, keySize); {
		case recordKey < key:
			lo = mid + 1
		case recordKey > key:
			hi = mid
		default:
			return readName(readOffset(table, pos+keySize)), true
		}
	}

	return "", false
}

// readKey decodes a big-endian key of the given size at the position.
func readKey(s string, pos, size int) uint32 {
	switch size {
	case 1:
		return uint32(s[pos])
	case 2:
		_ = s[pos+1]

		return uint32(s[pos])<<8 | uint32(s[pos+1])
	default:
		_ = s[pos+3]

		return uint32(s[pos])<<24 | uint32(s[pos+1])<<16 | uint32(s[pos+2])<<8 | uint32(s[pos+3])
	}
}

// readOffset decodes a big-endian name offset at the position.
func readOffset(s string, pos int) int {
	_ = s[pos+2]

	return int(s[pos])<<16 | int(s[pos+1])<<8 | int(s[pos+2])
}

// readName returns the length-prefixed name at the offset in the names blob.
func readName(offset int) string {
	length := int(names[offset])

	return names[offset+1 : offset+1+length]
}
